public class Main {
    static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) return false;
        }
        return true;
    }
    public static void main(String[] args) {
        for (int n = 2; n <= 30; n++) {
            if (isPrime(n)) System.out.print(n + " ");
        }
    }
}

