java.code:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> items = List.of(1, 2, 2, 3, 4, 4, 4, 5);
        Set<Integer> seen = new HashSet<>();
        Set<Integer> dup = new HashSet<>();
        for (int x : items) {
            if (!seen.add(x)) dup.add(x);
        }
        System.out.println("Duplicates: " + dup); // [2, 4]
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double a = sc.nextDouble();
        char op = sc.next().charAt(0);
        double b = sc.nextDouble();
        double result;
        switch (op) {
            case '+' -> result = a + b;
            case '-' -> result = a - b;
            case '*' -> result = a * b;
            case '/' -> result = a / b;
            default -> { result = 0; System.out.println("Invalid op"); }
        }
        System.out.println(a + " " + op + " " + b + " = " + result);
    }
}

import java.util.*;

class Student {
    String name; int total; double pct; String grade;
    Student(String n, int[] marks) {
        name = n; total = 0;
        for (int m : marks) total += m;
        pct = total / 3.0;
        grade = pct >= 90 ? "A" : pct >= 75 ? "B" : "C";
    }
}

public class Main {
    public static void main(String[] args) {
        List<Student> list = new ArrayList<>();
        list.add(new Student("Priya", new int[]{90, 85, 88}));
        for (Student s : list)
            System.out.printf("%s: %d/300 (%.1f%%) Grade %s%n", s.name, s.total, s.pct, s.grade);
    }
}
